def generate(level=1, **kwargs):
    dividend = [-7, 4, -1]
    divisor = [1, 2]

    q_coeffs, r_coeffs = PolynomialOps.div_qr(dividend, divisor)

    question_text = f"Divide the polynomial with coefficients {dividend} by the linear divisor with coefficients {divisor}. Report the quotient and remainder."

    return {
        "question_text": question_text,
        "correct_answer": {
